/* AUTO-GENERATED grapheme-to-reading rules. Unmapped characters pass through.
 * Latin languages carry a full ASCII base table plus their differences.
 * Brahmic scripts need the inherent-vowel engine (brahmic flag).
 * These are SPELLING-BASED approximations, not dictionary-grade IPA;
 * ipa-dict-data.ts supplies exact IPA for ~1000 common words per language.
 */

export interface TranslitRule {
  digraphs?: Record<string, string>
  chars?: Record<string, string>
  silent?: string
  post?: Array<[string, string]>
  brahmic?: { independent: string; signs: string; virama: string }
  /** When a spelling is already phonetic (Indonesian, Swahili...), split it
   *  into syllables so the ruby still teaches something. */
  syllabify?: boolean
}

